def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # In the final round, defection is weakly dominant because there is no future.
    if n == 99:
        return 'D'

    last_me, last_op = history[-1]

    opp_c = 0
    opp_d = 0
    my_d = 0

    recent10_opp_d = 0
    recent5_opp_d = 0
    recent5_my_d = 0
    recent3_my_d = 0

    for i, (m, o) in enumerate(history):
        if o == 'D':
            opp_d += 1
            if i >= n - 10:
                recent10_opp_d += 1
            if i >= n - 5:
                recent5_opp_d += 1
        else:
            opp_c += 1

        if m == 'D':
            my_d += 1
            if i >= n - 5:
                recent5_my_d += 1
            if i >= n - 3:
                recent3_my_d += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    # Clearly uncooperative opponent: defend permanently.
    if opp_c == 0:
        return 'D'

    # If the opponent has never defected, gradually test whether they are
    # exploitable. Once several probes are tolerated, exploit fully.
    if opp_d == 0:
        if n >= 60:
            if my_d >= 3:
                return 'D'
            if last_me == 'D':
                return 'C'
            return 'D'
        return 'C'

    coop_rate = opp_c / n

    chronic = (
        coop_rate <= 0.28
        or (recent10_opp_d >= 8 and n >= 10)
        or (opp_d > opp_c and coop_rate < 0.45)
    )

    if last_op == 'D':
        if chronic:
            return 'D'

        # If the opponent is in a long unbroken defection streak while we have
        # repeatedly cooperated, continuing to appease is unlikely to help.
        if n >= 2 and last_me == 'C' and history[-2][0] == 'C' and opp_d_streak >= 4:
            return 'D'

        # If we defected recently, their D is likely retaliation for our probe.
        # Repair instead of escalating.
        if recent3_my_d >= 1:
            if opp_d_streak >= 3 and coop_rate <= 0.35:
                return 'D'
            return 'C'

        # A longer defensive pattern against an opponent that is already
        # more defect than cooperate.
        if opp_d_streak >= 3 and opp_d > opp_c:
            return 'D'

        # Unprovoked defection: punish once.
        return 'D'

    # Opponent cooperated last round.
    if chronic:
        # Against mostly-defective opponents, do not remain soft unless they
        # appear to be in a rare cooperative phase.
        if recent10_opp_d >= 6 or coop_rate <= 0.22:
            return 'D'

    # Endgame opportunism against stable, forgiving, highly cooperative partners.
    if (
        n >= 98
        and coop_rate > 0.65
        and opp_d <= 3
        and recent5_opp_d == 0
        and recent5_my_d == 0
    ):
        return 'D'

    # Preserve cooperative equilibrium.
    return 'C'
